package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var LoanRecInst LoanRec
var inputLines []string
var inputIdx int

func parseDecimal(s string, scale int32) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.NewFromInt(0)
	}
	neg := false
	if trimmed[0] == '-' || trimmed[0] == '+' {
		if trimmed[0] == '-' {
			neg = true
		}
		trimmed = trimmed[1:]
		if trimmed == "" {
			return decimal.NewFromInt(0)
		}
	}
	n, err := strconv.ParseInt(trimmed, 10, 64)
	if err == nil {
		d := decimal.New(n, -scale)
		if neg {
			d = d.Neg()
		}
		return d
	}
	d, err2 := decimal.NewFromString(trimmed)
	if err2 != nil {
		return decimal.NewFromInt(0)
	}
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func parseInt(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	n, err := strconv.ParseInt(trimmed, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func truncDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	isNeg := v.Sign() < 0
	abs := v.Abs()
	s := abs.StringFixed(scale)
	var intPart, fracPart string
	if scale > 0 {
		idx := strings.LastIndex(s, ".")
		if idx >= 0 {
			intPart = s[:idx]
			fracPart = s[idx+1:]
			if len(fracPart) < int(scale) {
				fracPart = fracPart + strings.Repeat("0", int(scale)-len(fracPart))
			}
		} else {
			intPart = s
			fracPart = strings.Repeat("0", int(scale))
		}
	} else {
		intPart = s
		fracPart = ""
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	if intPart == "" {
		intPart = "0"
	}
	var recon string
	if scale > 0 {
		recon = intPart + "." + fracPart
	} else {
		recon = intPart
	}
	d, _ := decimal.NewFromString(recon)
	if isNeg {
		d = d.Neg()
	}
	return d
}

func truncInt(n int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if n >= 0 {
		return n % mod
	}
	abs := -n
	return -(abs % mod)
}

func roundHalfAway(v decimal.Decimal, scale int32) decimal.Decimal {
	factor := decimal.New(1, scale)
	shifted := v.Mul(factor)
	isNeg := shifted.Sign() < 0
	absShifted := shifted.Abs()
	truncAbs := absShifted.Truncate(0)
	frac := absShifted.Sub(truncAbs)
	half := decimal.New(5, -1) // 0.5
	if frac.Cmp(half) >= 0 {
		truncAbs = truncAbs.Add(decimal.NewFromInt(1))
	}
	if isNeg {
		truncAbs = truncAbs.Neg()
	}
	invFactor := decimal.New(1, -scale)
	return truncAbs.Mul(invFactor)
}

func formatEdited(value decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	isNeg := value.Sign() < 0
	abs := value.Abs()
	scaled := abs.Round(int32(fracDigits))
	var sFixed string
	if fracDigits > 0 {
		sFixed = scaled.StringFixed(int32(fracDigits))
	} else {
		sFixed = scaled.StringFixed(0)
	}
	var intPartStr, fracPartStr string
	if fracDigits > 0 {
		parts := strings.SplitN(sFixed, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = ""
		}
		if len(fracPartStr) < fracDigits {
			fracPartStr = fracPartStr + strings.Repeat("0", fracDigits-len(fracPartStr))
		} else if len(fracPartStr) > fracDigits {
			fracPartStr = fracPartStr[:fracDigits]
		}
	} else {
		intPartStr = sFixed
		fracPartStr = ""
	}
	if len(intPartStr) > intDigits {
		intPartStr = intPartStr[len(intPartStr)-intDigits:]
	}
	paddedInt := intPartStr
	if len(paddedInt) < intDigits {
		paddedInt = strings.Repeat("0", intDigits-len(paddedInt)) + paddedInt
	}
	outInt := make([]byte, len(intPic))
	placeholderIdx := 0
	suppress := true
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		if ch == ',' {
			if suppress {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if ch == 'Z' || ch == '9' {
			d := paddedInt[placeholderIdx]
			placeholderIdx++
			if suppress {
				if ch == 'Z' && d == '0' {
					outInt[i] = ' '
				} else {
					outInt[i] = d
					suppress = false
				}
			} else {
				outInt[i] = d
			}
		} else {
			outInt[i] = byte(ch)
		}
	}
	outFrac := make([]byte, len(fracPic))
	fIdx := 0
	for i := 0; i < len(fracPic); i++ {
		ch := fracPic[i]
		if ch == 'Z' || ch == '9' {
			if fIdx < len(fracPartStr) {
				outFrac[i] = fracPartStr[fIdx]
				fIdx++
			} else {
				outFrac[i] = '0'
			}
		} else {
			outFrac[i] = byte(ch)
		}
	}
	var result string
	if dotIdx >= 0 {
		result = string(outInt) + "." + string(outFrac)
	} else {
		result = string(outInt)
	}
	if isNeg {
		b := []byte(result)
		firstNonSpace := -1
		for i, c := range b {
			if c != ' ' {
				firstNonSpace = i
				break
			}
		}
		if firstNonSpace > 0 {
			b[firstNonSpace-1] = '-'
			result = string(b)
		} else if firstNonSpace == 0 {
			if len(b) > 0 {
				b = append([]byte{'-'}, b[1:]...)
				result = string(b)
			}
		}
	}
	return result
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func mainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = []string{}
			inputIdx = 0
			WsEofFlag = "Y"
		} else {
			fmt.Fprintf(os.Stderr, "open error: %v\n", err)
			os.Exit(1)
		}
	} else {
		content := string(data)
		content = strings.ReplaceAll(content, "\r\n", "\n")
		content = strings.ReplaceAll(content, "\r", "\n")
		if content == "" {
			inputLines = []string{}
		} else {
			lines := strings.Split(content, "\n")
			if strings.HasSuffix(content, "\n") {
				if len(lines) > 0 && lines[len(lines)-1] == "" {
					lines = lines[:len(lines)-1]
				}
			}
			inputLines = lines
		}
		inputIdx = 0
		WsEofFlag = "N"
	}
	readPara()
	for !isInputDone() {
		processPara()
	}
	summaryPara()
}

func readPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	LoanRecInst.LrAcct = line[0:6]
	LoanRecInst.LrPrincipal = parseDecimal(line[6:15], 2)
	LoanRecInst.LrRate = parseDecimal(line[15:19], 2)
	LoanRecInst.LrYears = parseInt(line[19:21])
}

func processPara() {
	raw := LoanRecInst.LrPrincipal.Mul(LoanRecInst.LrRate).Mul(decimal.NewFromInt(LoanRecInst.LrYears))
	rawDiv := raw.Mul(decimal.New(1, -2))
	rounded := roundHalfAway(rawDiv, 2)
	WsInterest = truncDecimal(rounded, 9, 2)
	newTotal := WsTotal.Add(WsInterest)
	WsTotal = truncDecimal(newTotal, 11, 2)
	WsCount = truncInt(WsCount+1, 5)
	WsPrinEd = formatEdited(LoanRecInst.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Println(LoanRecInst.LrAcct + " " + WsPrinEd + " " + WsIntEd)
	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Println("RECORDS: " + countStr)
	fmt.Println("TOTAL INTEREST: " + WsTotalEd)
}

func main() {
	mainPara()
}
